checks.solution:
class Node:
    def __init__(self, x, y, w, h):
        self.x, self.y, self.w, self.h = x, y, w, h
        self.left = None
        self.right = None
        self.room = None

    def leaves(self):
        if self.left is None and self.right is None:
            return [self]
        return self.left.leaves() + self.right.leaves()


def partition(x, y, w, h, min_size, cut, depth=0, max_depth=6):
    node = Node(x, y, w, h)
    if depth >= max_depth or (w < 2 * min_size and h < 2 * min_size):
        return node
    horizontal = h > w if h != w else cut(0, 1) == 1
    extent = h if horizontal else w
    if extent < 2 * min_size:
        horizontal = not horizontal
        extent = h if horizontal else w
        if extent < 2 * min_size:
            return node
    position = cut(min_size, extent - min_size)
    if not min_size <= position <= extent - min_size:
        raise ValueError("cut position leaves a partition below min_size")
    if horizontal:
        node.left = partition(x, y, w, position, min_size, cut, depth + 1, max_depth)
        node.right = partition(x, y + position, w, h - position, min_size, cut,
                               depth + 1, max_depth)
    else:
        node.left = partition(x, y, position, h, min_size, cut, depth + 1, max_depth)
        node.right = partition(x + position, y, w - position, h, min_size, cut,
                               depth + 1, max_depth)
    return node


def carve(node, inset, room_of):
    for leaf in node.leaves():
        if leaf.w <= 2 * inset or leaf.h <= 2 * inset:
            raise ValueError("a leaf is too small to inset a room into")
        leaf.room = room_of(leaf.x + inset, leaf.y + inset,
                            leaf.w - 2 * inset, leaf.h - 2 * inset)
    return node


def _centre(node):
    if node.room is not None:
        x, y, w, h = node.room
        return (x + w // 2, y + h // 2)
    return _centre(node.left) if node.left is not None else None


def corridors(node):
    if node.left is None and node.right is None:
        return []
    out = corridors(node.left) + corridors(node.right)
    out.append((_centre(node.left), _centre(node.right)))
    return out
